command:example.dev:code:
PS C:\> $properties = @{
    domain   = 'company.com'
    ou       = 'cn=mygroup'
    targets  = @{ domainController = $true; nonPrivileged = $true }
    adGroups = @{ groups = $true }
}
PS C:\> $credentials = @(
    @{ name = 'DOMAIN_ADMIN'; type = 'ACCOUNT'; properties = @{ account_id = '111_5' } }
)
PS C:\> Add-DMDiscoveryScanDefinition -name Windows-nix-scan -type WIN_NIX_DOMAIN -networkId dsdfsdf-5342-asdb-bd22-sdfdg3425 -properties $properties -credentials $credentials -recurrenceType IMMEDIATE -State ACTIVE

PS C:\> $properties = @{
    domain                   = 'company.com'
    resource                 = @{ id = '980ece7a-a4de-43ac-a61b-fake' }
    certificateConfiguration = @{ validateCertificate = $true }
}
PS C:\> $credentials = @(
    @{ name = 'DOMAIN_ADMIN'; type = 'ACCOUNT'; properties = @{ account_id = '82_5' } }
)
PS C:\> $recurrenceData = @{
    date          = '2025-12-15'
    times         = @('13:30')
    timeZone      = 'US'
    repeatPattern = 'WEEKLY'
    daysOfWeek    = @('TUESDAY')
}
PS C:\> Add-DMDiscoveryScanDefinition -name SQLScan -type SQL_SERVER -networkId 353e85d5-4671-4ghjghg-ghjgee -tags tag1 -properties $properties -credentials $credentials -recurrenceType RECURRING -recurrenceData $recurrenceData -State INACTIVE

PS C:\> $machineList = @(
    New-DMDiscoveryScanResourceMachineObject -Address sampleaddress.com -Tags sampleTag
)
PS C:\> Add-DMDiscoveryScanResource -type WIN_NIX_LIST -name list_scan_sample.csv -content @{machineList = $machineList}

PS C:\> $machineList = @(
    New-DMDiscoveryScanResourceMachineObject -Address address1.com -Username domainUserName -Database DatabaseName1 -Port 1433 -Domain Domain.com -Tags Tag1 -Instances *
)
PS C:\> Add-DMDiscoveryScanResource -type SQL_SERVER -name sql_server_scan.csv -content @{machineList = $machineList}

PS C:\> $machineList = @(
    New-DMDiscoveryScanResourceMachineObject -Address address1.com -Username domainUserName -Database DatabaseName1 -Port 1433 -Domain Domain.com -Tags Tag1 -Instances *
    New-DMDiscoveryScanResourceMachineObject -Address address2.com -Username domainUserName -Database DatabaseName2 -Port 1433 -Domain Domain.com
)
PS C:\> Add-DMDiscoveryScanResource -type SQL_SERVER -name sql_server_scan.csv -content @{machineList = $machineList}

PS C:\> $properties = @{
    domain   = 'company.com'
    ou       = 'cn=mygroup'
    targets  = @{ domainController = $true; nonPrivileged = $false }
    adGroups = @{ groups = $true }
}
PS C:\> Set-DMDiscoveryScanDefinition -id d571cdfgdfg8 -properties $properties
